#!/usr/bin/env bash
# Doc admin « Le droit à l'image des photos », doc membre « Où j'apparais », tuto du rapport.
# Prérequis : apply-docs-refus-photo.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-tutos-droit-image.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/tours/definitions/admin.droit-image.photos.ts" 2>/dev/null | grep -qF "export const adminDroitImagePhotos"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### Refuser une photo précise" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-refus-photo.sh puis apply-docs-refus-photo.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/creer-une-galerie.mdx" "apps/web/content/docs/guide/mon-profil.mdx" "apps/web/src/features/admin/media-people/PublicRightsReport.tsx" "apps/web/src/features/image-consent/MyAppearances.tsx" "apps/web/src/features/tours/definitions/admin.galleries.create.ts" "apps/web/src/features/tours/tour.registry.ts" "e2e/tutos-admin.spec.ts")
CREATED=("apps/web/content/docs/admin/droit-a-l-image-des-photos.mdx" "apps/web/content/docs/guide/ou-j-apparais.mdx" "apps/web/src/features/tours/definitions/admin.droit-image.photos.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export const adminDroitImagePhotos" "apps/web/src/features/tours/definitions/admin.droit-image.photos.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/admin"
